    import sys
    k = int(sys.stdin.readline())
    if k == 1:
        print(2)
        print("NY")
        print("YN")
    else:
        n = 2
        while True:
            if k == 1:
                break
            if k % 2 == 0:
                n += 1
                k //= 2
            else:
                n += 2
                k = (k - 1) // 2
        print(n)
        adj = [['N'] * n for _ in range(n)]
        adj[0][1] = 'Y'
        adj[1][0] = 'Y'
        for i in range(2, n):
            adj[0][i] = 'Y'
            adj[i][0] = 'Y'
            adj[i][1] = 'Y'
            adj[1][i] = 'Y'
        for i in range(n):
            print(''.join(adj[i]))

